fn interpolate_string(
    mut name_to_index: Vec<(&'static str, usize)>,
    caps: Vec<&'static str>,
    replacement: &str,
) -> String {
    name_to_index.sort_by_key(|x| x.0);

    let mut dst = vec![];
    interpolate(
        replacement.as_bytes(),
        |i, dst| {
