./tests/misc.rs:634:rgtest!(ignore_git_parent_stop, |dir: Dir, mut cmd: TestCommand| {
./tests/misc.rs:635:    // This tests that searching parent directories for .gitignore files stops
./tests/misc.rs:636:    // after it sees a .git directory. To test this, we create this directory
./tests/misc.rs:637:    // hierarchy:
./tests/misc.rs:638:    //
./tests/misc.rs:639:    // .gitignore (contains `sherlock`)
./tests/misc.rs:640:    // foo/
./tests/misc.rs:641:    //   .git/
./tests/misc.rs:642:    //   bar/
./tests/misc.rs:643:    //      sherlock
./tests/misc.rs:644:    //
./tests/misc.rs:645:    // And we perform the search inside `foo/bar/`. ripgrep will stop looking
./tests/misc.rs:646:    // for .gitignore files after it sees `foo/.git/`, and therefore not
./tests/misc.rs:647:    // respect the top-level `.gitignore` containing `sherlock`.
