    {
        let &mut Space { ref mut dst, ref mut caps, ref mut matches } =
            self.allocate(matcher)?;
        dst.clear();
        matches.clear();

        replace_with_captures_in_context(
            matcher,
            haystack,
            line_terminator,
            range.clone(),
            caps,
            dst,
            |caps, dst| {
                let start = dst.len();
                caps.interpolate(
                    |name| matcher.capture_index(name),
